// Partner logos for the top of the line panel, beside the Aerchain wordmark.
// Both are one-colour traces, so the canvas can colour them line by line
// the way it colours the wordmark.
// - et: The Economic Times, traced (potrace) from the ET | CPO'26 lockup the
//   owner pasted; the red square is solid with "ET" cut out of it.
// - cpo26: CPO'26 Industrial Procurement Summit, the trace made for the
//   aerchain-cpo26-delhi film.
// Each path is in potrace units; `matrix` maps it to the logo box, whose
// top-left corner is 0,0 and whose size is width x height.

export type PartnerId = "et" | "cpo26";

// The ET square in its own red, measured from the owner's ET artwork, with
// "ET" in white. `box` is the square in logo units (x, y, width, height).
export const ET_RED = "#D63540";

